/**
 * End-to-end showcase: builds a 30-second original film that exercises the
 * features shipped this week (timeline placement, keyframe easing, text
 * animation, subtitle split/merge, loudness normalization, speech ducking,
 * templates) and exports it with the real FFmpeg pipeline.
 *
 * Run: npx tsx scripts/generate-showcase.ts [outputDir]
 * Everything is synthetic and generated by this file (MIT).
 */
import { mkdir, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { createCanvas, type SKRSContext2D } from "@napi-rs/canvas";
import {
  createClip,
  createProject,
  createTrack,
  id,
  splitClip,
  validateProject,
} from "../src/core/model";
import { BUILTIN_TEMPLATES } from "../src/core/builtinTemplates";
import { instantiateTemplate, templateFromProject } from "../src/core/templates";
import { prepareDucking } from "../src/core/audioMix";
import { prepareSubtitleEdit } from "../src/core/subtitleEdits";
import type { TextAnimationSettings } from "../src/core/textAnimation";
import { importAssets, probeFile, runMediaTool } from "../electron/media";
import { measureLoudness } from "../electron/loudness";
import { prepareAudioNormalization } from "../src/core/audioMix";
import { startExport } from "../electron/export";
import type { Clip, MediaAsset, Project } from "../src/core/types";

const WIDTH = 1280;
const HEIGHT = 720;
const FPS = 30;
const SCENE = 8;
const SHOWCASE_SECONDS = 30;

const palettes = [
  { sky: "#0f2b3a", mid: "#1d5a66", low: "#2f8b86", ink: "#08202b", sun: "#ffd9a8" },
  { sky: "#1b2440", mid: "#3a3f74", low: "#6b5f9e", ink: "#121633", sun: "#ffe7c4" },
  { sky: "#2a1c2b", mid: "#6b3a4c", low: "#c0705d", ink: "#1a0f17", sun: "#fff0d0" },
];

function scene(context: SKRSContext2D, index: number) {
  const palette = palettes[index];
  const sky = context.createLinearGradient(0, 0, 0, HEIGHT);
  sky.addColorStop(0, palette.sky);
  sky.addColorStop(0.58, palette.mid);
  sky.addColorStop(1, palette.low);
  context.fillStyle = sky;
  context.fillRect(0, 0, WIDTH, HEIGHT);
  const sunX = WIDTH * [0.74, 0.26, 0.5][index];
  const glow = context.createRadialGradient(sunX, HEIGHT * 0.28, 8, sunX, HEIGHT * 0.28, 260);
  glow.addColorStop(0, palette.sun);
  glow.addColorStop(0.35, `${palette.sun}66`);
  glow.addColorStop(1, "transparent");
  context.fillStyle = glow;
  context.fillRect(0, 0, WIDTH, HEIGHT);
  context.fillStyle = palette.sun;
  context.beginPath();
  context.arc(sunX, HEIGHT * 0.28, 42, 0, Math.PI * 2);
  context.fill();
  // Layered ridges.
  for (let layer = 0; layer < 4; layer++) {
    const base = HEIGHT * (0.62 + layer * 0.085);
    const amplitude = 90 - layer * 14;
    context.beginPath();
    context.moveTo(0, HEIGHT);
    for (let x = 0; x <= WIDTH; x += 32) {
      const y =
        base -
        Math.abs(Math.sin(x / 210 + index * 1.7 + layer)) * amplitude -
        Math.sin(x / 57 + layer) * 8;
      context.lineTo(x, y);
    }
    context.lineTo(WIDTH, HEIGHT);
    context.closePath();
    context.fillStyle = [
      `${palette.ink}55`,
      `${palette.ink}88`,
      `${palette.ink}bb`,
      palette.ink,
    ][layer];
    context.fill();
  }
  // Foreground grain lines keep the still image alive under the zoom.
  context.strokeStyle = "#ffffff12";
  context.lineWidth = 1;
  for (let i = 0; i < 24; i++) {
    const y = HEIGHT * 0.7 + i * 9;
    context.beginPath();
    context.moveTo(0, y);
    context.lineTo(WIDTH, y + Math.sin(i) * 4);
    context.stroke();
  }
}

function textClip(
  project: Project,
  trackId: string,
  start: number,
  duration: number,
  value: string,
  options: {
    size: number;
    y: number;
    color?: string;
    background?: string;
    padding?: number;
    radius?: number;
    bold?: boolean;
  },
): Clip {
  const clip = createClip(undefined, trackId, start, project.fps);
  clip.duration = duration;
  clip.text = {
    ...clip.text!,
    text: value,
    fontSize: options.size,
    color: options.color ?? "#ffffff",
    background: options.background ?? "transparent",
    padding: options.padding ?? 0.3,
    radius: options.radius ?? 0.4,
    strokeWidth: 0,
    bold: options.bold ?? true,
    shadow: { color: "#00000099", blur: 18, offsetX: 0, offsetY: 4 },
  };
  clip.name = value.slice(0, 60);
  clip.transform.y = options.y;
  return clip;
}

const ANIMATION: TextAnimationSettings = {
  entrance: "slideUp",
  hold: "pulse",
  exit: "fade",
  inDuration: 0.5,
  outDuration: 0.4,
};

export async function generateShowcase(directory = path.resolve(".demo")) {
  await mkdir(directory, { recursive: true });
  const images: string[] = [];
  for (let index = 0; index < 3; index++) {
    const canvas = createCanvas(WIDTH, HEIGHT);
    scene(canvas.getContext("2d"), index);
    const file = path.join(directory, `sahne-${index + 1}.png`);
    await writeFile(file, canvas.toBuffer("image/png"));
    images.push(file);
  }
  const narrationFile = path.join(directory, "anlati.wav");
  await runMediaTool("ffmpeg", [
    "-v", "error", "-y",
    "-f", "lavfi",
    "-i",
    "aevalsrc=0.32*(0.6*sin(2*PI*180*t)+0.25*sin(2*PI*360*t)+0.15*sin(2*PI*540*t))*(0.55+0.45*sin(2*PI*3.1*t)):s=48000:d=30",
    "-c:a", "pcm_s16le", narrationFile,
  ]);
  const musicFile = path.join(directory, "muzik.wav");
  await runMediaTool("ffmpeg", [
    "-v", "error", "-y",
    "-f", "lavfi",
    "-i",
    "aevalsrc=0.12*(0.5*sin(2*PI*220*t)+0.3*sin(2*PI*277.18*t)+0.2*sin(2*PI*329.63*t))*(0.7+0.3*sin(2*PI*0.09*t)):s=48000:d=30",
    "-c:a", "pcm_s16le", musicFile,
  ]);
  const assets = await importAssets(
    [...images, narrationFile, musicFile],
    path.join(directory, "cache"),
  );
  const [first, second, third, narration, music] = assets as MediaAsset[];

  const project = createProject("CevikEdit · hafta demosu");
  project.width = WIDTH;
  project.height = HEIGHT;
  project.fps = FPS;
  project.background = "#0b1016";
  project.assets = assets;

  const videoTrack = project.tracks.find((track) => track.kind === "video")!;
  const audioTrack = project.tracks.find((track) => track.kind === "audio")!;
  const titleTrack = createTrack("text", "Başlıklar");
  const subtitleTrack = createTrack("text", "Altyazılar");
  project.tracks = [subtitleTrack, titleTrack, videoTrack, audioTrack];

  // 1) Template scene: a real built-in template instantiated with our media;
  //    its title style and entrance animation are reused by the opening shot.
  const template = instantiateTemplate(BUILTIN_TEMPLATES[0], {
    name: "Açılış",
    media: { m1: first },
    texts: { [BUILTIN_TEMPLATES[0].texts[0].key]: "CevikEdit" },
  });
  validateProject(template.project);
  const templateTitle = template.project.clips.find(
    (clip) => clip.text && clip.id === template.clipIds[BUILTIN_TEMPLATES[0].texts[0].key],
  )!;
  const templateSubtitle = template.project.clips.find(
    (clip) => clip.text && clip.id !== templateTitle.id,
  )!;
  const opening = createClip(undefined, titleTrack.id, 0.5, FPS);
  opening.duration = 3.6;
  opening.text = {
    ...templateTitle.text!,
    text: "CevikEdit",
    fontSize: 132,
  };
  opening.transform.y = -140;
  opening.fadeIn = templateTitle.fadeIn;
  opening.fadeOut = templateTitle.fadeOut;
  opening.keyframes = templateTitle.keyframes.map((key) => ({
    ...key,
    id: id(),
    time: Math.min(key.time, opening.duration),
  }));
  opening.name = "CevikEdit";
  project.clips.push(opening);
  for (let index = 0; index < 3; index++) {
    const start = index * SCENE;
    const source = [first, second, third][index];
    const clip = createClip(source, videoTrack.id, start, FPS);
    clip.duration = index === 2 ? SHOWCASE_SECONDS - start : SCENE;
    clip.name = ["Sabah ışığı", "Açık su", "Gün batımı"][index];
    clip.fadeIn = index === 0 ? 0.7 : 0.3;
    clip.fadeOut = 0.3;
    clip.adjustments = {
      ...clip.adjustments,
      brightness: 0.01,
      contrast: 1.05,
      saturation: 0.97,
      temperature: [0.06, -0.03, -0.05][index],
    };
    clip.keyframes = [
      { id: id(), time: 0, property: "scale", value: 1, easing: "linear" },
      {
        id: id(),
        time: clip.duration,
        property: "scale",
        value: 1.07,
        easing: "easeInOut",
      },
    ];
    project.clips.push(clip);
    const heading = textClip(
      project,
      titleTrack.id,
      start + 0.2,
      4.4,
      ["Sabah ışığı", "Açık su", "Gün batımı"][index],
      { size: 74, y: -180 },
    );
    heading.fadeIn = 0.5;
    heading.fadeOut = 0.4;
    project.clips.push(heading);
  }

  // 2) Subtitles with the uniform entrance/hold/exit animation.
  const cues = [
    ["Her şey bu bilgisayarda kalır", 1.2, 5.2],
    ["Kes, böl, yerleştir", 8.4, 13.4],
    ["Anahtar karelerle hareket", 15.6, 20.4],
    ["Konuşurken müzik kısılır", 21.6, 26.0],
    ["Şablonla saniyeler içinde başla", 26.4, 30.0],
  ] as const;
  let subtitleProject: Project = project;
  for (const [text, start, end] of cues) {
    const clip = textClip(subtitleProject, subtitleTrack.id, start, end - start, text, {
      size: 40,
      y: 280,
      background: templateSubtitle.text!.background,
      padding: templateSubtitle.text!.padding,
      radius: templateSubtitle.text!.radius,
    });
    subtitleProject.clips.push(clip);
  }
  project.clips = subtitleProject.clips;
  const animated = prepareSubtitleEdit(project, project.clips.filter((clip) => clip.trackId === subtitleTrack.id).map((clip) => clip.id), {
    type: "animation",
    animation: ANIMATION,
  });
  project.clips = animated.project.clips;

  // 3) Split then merge one cue to prove both rules inside the film project.
  const longest = project.clips
    .filter((clip) => clip.trackId === subtitleTrack.id)
    .sort((a, b) => b.duration - a.duration)[0];
  const split = prepareSubtitleEdit(project, [longest.id], {
    type: "split",
    at: longest.start + longest.duration / 2,
  });
  project.clips = split.project.clips;
  const parts = project.clips.filter((clip) => clip.trackId === subtitleTrack.id);
  const mergedId = project.clips.find(
    (clip) => clip.id === longest.id,
  )!.id;
  const partner = split.changedIds.find((clipId) => clipId !== mergedId)!;
  const merged = prepareSubtitleEdit(project, [mergedId, partner], { type: "merge" });
  project.clips = merged.project.clips;

  // 4) Narration segments and a music bed, then real loudness measurement,
  //    normalization and speech-driven ducking.
  const narrationClip = createClip(narration, audioTrack.id, 0, FPS);
  narrationClip.duration = 30;
  narrationClip.name = "anlatı";
  narrationClip.volume = 0.9;
  project.clips.push(narrationClip);
  const musicClip = createClip(music, audioTrack.id, 0, FPS);
  musicClip.duration = 30;
  musicClip.name = "müzik";
  musicClip.volume = 0.5;
  musicClip.audioFadeIn = 1;
  musicClip.audioFadeOut = 1.6;
  project.clips.push(musicClip);

  const measured = await measureLoudness({
    source: music.path,
    sourceIn: 0,
    duration: 30,
    speed: 1,
  });
  const normalized = prepareAudioNormalization(project, musicClip.id, measured, -20);
  project.clips = normalized.project.clips;
  const ducked = prepareDucking(project, [narrationClip.id], [musicClip.id], {
    amountDb: -11,
    fade: 0.5,
  });
  project.clips = ducked.project.clips;

  validateProject(project);
  const projectPath = path.join(directory, "showcase.cevikedit");
  await writeFile(projectPath, JSON.stringify(project, null, 2));

  // Also save the film project itself as a reusable template (round trip).
  const savedTemplate = templateFromProject(project, {
    name: "Hafta demosu",
    description: "Otuz saniyelik gösterim projesi; medya ve metin yer tutucularıyla.",
  });
  await writeFile(
    path.join(directory, "hafta-demosu.cevikedit-template"),
    JSON.stringify(savedTemplate, null, 2),
  );

  const output = path.join(directory, "showcase.mp4");
  await new Promise<void>((resolve, reject) => {
    void startExport(
      project,
      {
        path: output,
        width: WIDTH,
        height: HEIGHT,
        fps: FPS,
        quality: "high",
        format: "mp4",
      },
      (event) => {
        if (event.status === "complete") resolve();
        if (event.status === "error" || event.status === "cancelled")
          reject(new Error(event.message ?? event.status));
      },
    ).catch(reject);
  });
  const probe = await probeFile(output);
  const videoStream = probe.streams.find((stream) => stream.codec_type === "video");
  const duration = Number(probe.format.duration);
  if (
    !videoStream ||
    videoStream.width !== WIDTH ||
    videoStream.height !== HEIGHT ||
    duration < 29.5 ||
    duration > 31 ||
    !probe.streams.some((stream) => stream.codec_type === "audio")
  )
    throw new Error("Gösterim videosu doğrulanamadı");
  for (const [index, second] of [1.5, 9.5, 17.5, 24.5, 28.5].entries())
    await runMediaTool("ffmpeg", [
      "-v", "error", "-y",
      "-ss", String(second), "-i", output,
      "-frames:v", "1",
      path.join(directory, `onizleme-${index + 1}.png`),
    ]);
  await writeFile(
    path.join(directory, "KAYNAK.txt"),
    "Bu video scripts/generate-showcase.ts tarafından üretildi. Tüm görseller, altyazılar ve sesler bu betikte sentezlenmiştir; indirilmiş veya üçüncü tarafa ait medya yoktur. Üretici kaynak ve çıktılar MIT lisanslıdır.\n",
  );
  return {
    projectPath,
    templatePath: path.join(directory, "hafta-demosu.cevikedit-template"),
    output,
    duration,
    width: videoStream.width,
    height: videoStream.height,
    loudness: measured,
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  console.log(await generateShowcase(process.argv[2] ? path.resolve(process.argv[2]) : undefined));
